# mixture regression article
fr <- mixture_regression(score ~ hours, data = study_hours, n_classes = 2, n_starts = 5, seed = 1)
print(fr); print(get_results(fr, "coefficients")); 
ws <- mixture_regression(score ~ hours, data = study_hours, n_classes = 2, membership = ~ sleep, n_starts = 5, seed = 1)
print(get_results(ws, "coefficients")); print(as.data.frame(get_results(ws, "membership")))
st <- mixture_regression(passed ~ hours, data = study_hours, n_classes = 2, family = "binomial", id = "student", class_level = "group", membership = ~ motivation, n_starts = 5, seed = 1)
print(as.data.frame(get_results(st, "membership"))); print(get_results(st,"coefficients"))
print(get_results(st, "recovery", data = study_hours, truth = "student_type"))
tl <- mixture_regression(score ~ hours, data = study_hours, n_classes = 2, id = "student", n_group_classes = 2, membership = ~ sleep, group_membership = ~ motivation, n_starts = 5, seed = 1)
